import{_ as r,l as i,o as a,c as s,v as n,p as l,x as o,d as m,i as h,S as c}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"企业异质性与投资","description":"","frontmatter":{"title":"企业异质性与投资","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/firm-heterogeneity-investment.md","filePath":"econ/firm-heterogeneity-investment.md","lastUpdated":1789023840000}'),p={name:"econ/firm-heterogeneity-investment.md"};function d(E,e,_,u,f,B){const t=i("Mermaid");return a(),s("div",null,[e[1]||(e[1]=n('<h1 id="企业异质性与投资" tabindex="-1">企业异质性与投资 <a class="header-anchor" href="#企业异质性与投资" aria-label="Permalink to &quot;企业异质性与投资&quot;">​</a></h1><div class="epigraph"><p>固定成本与不可逆使投资变成 $(S,s)$；加总 $I$ 的平滑来自企业分布在阈值上的积分，不是代表性凸调整成本那么干净。</p><footer>—— Hopenhayn, Entry, Exit and Firm Dynamics, Econometrica 1992；Khan and Thomas, Idiosyncratic Shocks and the Role of Nonconvexities, Econometrica 2008</footer></div><p><a href="/econ/household-debt-cycles">上一课</a>把家庭杠杆接到需求。供给与资本积累仍常被写成代表性 \\(q\\)。本课缺口是<strong>企业异质</strong>：生产率分布、进入退出、非凸投资。异质单元在此收束。不重写按揭 MPC，不把托宾 \\(q\\) 的定义再推一遍。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/econ/tobin-q">托宾 q</a> 给了边际影子价格。凸调整成本让代表性 \\(I(q)\\) 光滑。微观：投资 lumpy（Doms–Dunne、Cooper–Haltiwanger）。Caballero–Engel 的 \\((S,s)\\)：加总来自多少企业越过阈值。Khan–Thomas：一般均衡价格反馈可以削弱非凸对加总的影响。Hopenhayn：进入退出与平稳的企业规模分布。缺口是：加总投资脉冲不必等于代表性 \\(q\\) 回归，即使每家企业盯着自己的 \\(q\\)。</p><p><span class="marginnote">Hopenhayn, <em>Econometrica</em> 1992。Khan and Thomas, <em>Econometrica</em> 2008。Winberry 把 lumpy 投资接到 NK。Gabaix 的颗粒度：大企业冲击可进总量。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>企业状态：生产率、资本、可能还有债务约束。决策：投资、进入、退出。出清：工资与利率（或需求）由分布决定。求解：与 KS 类似的预报定律，或序列空间。校准：企业层面投资率的分布、进入率、就业再配置。金融摩擦：外部融资溢价对企业规模异质（Gomes；Bernanke–Gertler–Gilchrist 的加速器是代表性或代表性「企业家」），后单元再接到中介。</p>',8)),(a(),l(c,null,{default:o(()=>[h(t,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20Z%5B%22%E4%BC%81%E4%B8%9A%E7%94%9F%E4%BA%A7%E7%8E%87%22%5D%20--%3E%20SS%5B%22(S%2Cs)%20%E6%8A%95%E8%B5%84%22%5D%0A%20%20DIST%5B%22%E4%BC%81%E4%B8%9A%E5%88%86%E5%B8%83%22%5D%20--%3E%20AGG%5B%22%E5%8A%A0%E6%80%BB%20I%22%5D%0A%20%20SS%20--%3E%20AGG%0A%20%20P%5B%22GE%20%E4%BB%B7%E6%A0%BC%22%5D%20--%3E%20SS%0A%20%20ENT%5B%22%E8%BF%9B%E5%85%A5%E9%80%80%E5%87%BA%22%5D%20--%3E%20DIST%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[m(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n('<p>颗粒度（Gabaix）：尾部企业足够大时，特异冲击不抵消。这与家庭帕累托尾是姐妹，对象换成企业销售。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是阈值加分布。总量冲击移动阈值或移动分布质量，加总 \\(I\\) 可以出现急促或延迟。GE：利率与工资吸收部分特异需求，Khan–Thomas 强调这一点，避免从微观 lumpy 直接推出宏观 lumpy。误配（Hsieh–Klenow）是另一条：摩擦使 \\(MRPK\\) 分散，TFP 下降——增长课已有接口，本课只点名周期与投资。</p><p>与 HANK：家庭 MPC 分布 × 企业投资分布 = 需求冲击的供给响应。两套分布都不是代表性弹性。</p><p><span class="marginnote">本课不把产业组织的全部进入模型搬进来。也不估计股票横截面的投资因子——那是资产定价课。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写最优产业政策。不把信贷周期的抵押约束当主方程（下一单元 KM）。预期如何形成仍用理性预期；下一单元才改预期算子。异质单元结束：后课默认家庭与企业都可以是分布，加总矩不够识别微观弹性。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>非凸投资与进入退出使加总 \\(I\\) 成为分布的积分。</li><li>GE 价格可削弱微观 lumpy 向宏观的传递。</li><li>颗粒度让大企业冲击进入总量。</li><li>出处：Hopenhayn, <em>Econometrica</em> 1992；Khan and Thomas, <em>Econometrica</em> 2008。</li></ul>',9))])}const S=r(p,[["render",d]]);export{T as __pageData,S as default};
